SET IDENTITY_INSERT Posts ON;
INSERT INTO Posts(
    id, user_id, user_type, parent_id, post_type, title, status, view_count, like_count, 
    comment_count, created_at, updated_at, deleted_at, experience, deadline, working_time, 
    job_description, requirements, benefits, contact_address, application_method, company_name, 
    salary, location, job_type, company_logo, quantity, rank, industry, contact_person, 
    company_size, company_website, company_description, keywords
) VALUES 
(19, 1, 'recruiter', NULL, 'post', N'Kiến Trúc Sư 3D [Hà Nội] - Lương Cơ Bản Upto 17Tr+++, Tối Thiểu 1 Năm Kinh Nghiệm', 'active', 25, 0, 0, '2025-06-02 21:00:44.083', '2025-06-30 19:33:52.173', NULL, '1 năm', '2025-07-04', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00) Thứ 7 (từ 08:00 đến 12:00)', '<ul><li>Lên ý tưởng Tổng mặt bằng, và hình khối theo yêu cầu chủ đầu tư</li><li>Triển khai hồ sơ và xuất bản vẽ TKCS</li><li>Diễn họa 3D công trình xuất từ sketchup và render bằng phần mềm (Lumion, Enscape, vray...)</li><li>Triển khai bản vẽ Shopdrawing bằng bằng autocad cho các dự án thi công.</li><li>Các công việc khác theo sự phân công của quản lý trực tiếp</li></ul>', '<ul><li>Tốt nghiệp Đại học chuyên ngành Kiến Trúc Công Trình</li><li>Yêu cầu kinh nghiệm từ 1- 2 năm ở vị trí tương đương</li><li>Ưu tiên ứng viên có kỹ năng diễn họa 3D tốt</li><li>Ứng viên biết Revit là một lợi thế (hoặc được đào tạo khi trở thành nhân viên chính thức)</li><li>Chưa có kinh nghiệm về công trình thương mại, và công trình công nghiệp sẽ được đào tạo.</li></ul>', '<ul><li>Mức lương upto 17 triệu (thỏa thuận tùy năng lực và kinh nghiệm làm việc thực tế)</li><li>Tham gia BHXH, BHYT, BHTN; Khám sức khỏe định kỳ...;</li><li>Lương tháng 13, thưởng doanh thu và thưởng dự án;</li><li>Thưởng các ngày lễ, tết</li><li>Chế độ nghỉ phép: theo luật lao động;</li><li>Du lịch hè hàng năm;</li><li>Chế độ công đoàn;</li><li>Tham gia các chương trình đào tạo kỹ năng và chuyên môn;</li><li>Chính sách khuyến khích nâng cao kỹ năng ngoại ngữ & chứng chỉ năng lực chuyên môn;</li><li>Môi trường năng động, chuyên nghiệp, thân thiện, có nhiều cơ hội phát triển.</li></ul>', 'Tầng 5, Tòa Nhà Báo Nông thôn ngày nay, Ngõ 68 Dương Đình Nghệ, Cầu Giấy, Hà Nội', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'Công ty cổ phần tư vấn và xây dựng KM Việt Nam', 'Tới 17 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286832172_KMCC.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(20, 1, 'recruiter', NULL, 'post', N'Streamer Livestream Game TikTok ( Tuyển Nữ) Thu Nhập Cao Lương Cứng Upto 15Tr + Thưởng KPI Không Giới Hạn - Đào Tạo Từ Đầu Đi Làm Ngay', 'active', 48, 0, 0, '2025-06-02 21:01:21.823', '2025-06-30 19:33:37.880', NULL, 'Không yêu cầu', '2025-07-30', 'Thứ 2 - Thứ 6 (từ 09:00 đến 18:00) Thứ 7 9:00 đến 18:00 (làm việc cách tuần). (Livestream 4 – 5 tiếng mỗi ngày).Khi live cứng chỉ cần lên live từ 4-5 tiếng mỗi ngày.', '<ul><li>Livestream chơi game trên nền tảng TikTok (không giới hạn thể loại game).</li><li>Tương tác trực tiếp với người xem trong suốt quá trình livestream, tạo nội dung hấp dẫn nhằm thu hút người theo dõi.</li><li>Hỗ trợ lên ý tưởng và cắt dựng video ngắn (clip highlight) từ các buổi livestream để đăng tải lên TikTok, Instagram hoặc Facebook.</li><li>Đảm bảo chất lượng hình ảnh, âm thanh và đường truyền ổn định xuyên suốt buổi phát sóng.</li><li>Thời gian đầu làm việc từ Thứ 2-6 từ 9:00 đến 18:00, T7 cách tuần (Livestream 4 – 5 tiếng mỗi ngày). Khi live cứng chỉ cần lên live từ 4-5 tiếng mỗi ngày.</li></ul>', '<ul><li><strong>Giới tính: Nữ, độ tuổi từ 18 – 28</strong>, biết trang điểm cơ bản.</li><li>Tự tin, hoạt ngôn, biểu cảm tốt, giao tiếp linh hoạt, biết tương tác, trò chuyện cùng người xem.</li><li>Yêu thích và đam mê chơi game (mọi thể loại đều được).</li><li>Tác phong chuyên nghiệp, năng động, sáng tạo, có tinh thần trách nhiệm trong công việc.</li><li>Có kinh nghiệm livestream là một lợi thế, chưa có sẽ được đào tạo</li></ul>', '<ul><li>Thu nhập ổn định: <strong>Lương cứng hàng tháng 12- 15 triệu</strong> + <strong>Thưởng KPI hấp dẫn từ 15%-30%</strong></li><li>Được đào tạo bài bản, phát triển kỹ năng livestream, xây dựng hình ảnh cá nhân.</li><li>Hỗ trợ đầy đủ thiết bị livestream chuyên nghiệp.</li><li>Môi trường làm việc trẻ trung, năng động, sẵn sàng hỗ trợ và đồng hành cùng bạn lâu dài.</li><li>Cơ hội thăng tiến trong ngành giải trí, nội dung số và livestream.</li></ul>', '- Hồ Chí Minh: 117A Nguyễn Tất Thành Phường 13, Quận 4', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'CÔNG TY TNHH GAMETOK LIVE', 'Thoả thuận', 'Hồ Chí Minh', 'Full-time', 'uploads/company_logos/1751286817879_cty tnhh gametok live.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(115, 1, 'recruiter', NULL, 'post', N'Kỹ Sư Kỹ Thuật Xây Dựng/ Kết Cấu Công Trình Dân Dụng, Công Nghiệp/ Trắc Địa Bản Đồ', 'active', 32, 0, 0, '2025-06-03 20:01:44.007', '2025-06-30 19:33:18.950', NULL, '1 năm', '2025-07-11', '1. Thử việc: trong thời gian 60 ngày với mức lương thử việc – 10.000.000đ/tháng. 2. Chế độ công tác: - Đi công tác được nghỉ tại khách sạn với chi phí tối đa 1.100.000 đồng/ngày/phòng. - Mức công t', '<p>- Tư vấn thiết kế công trình hạ tầng kỹ thuật viễn thông: Tuyến cáp đồng, quang, Cơ sở hạ tầng trạm thu phát sóng (cột anten, nhà trạm, tiếp đất chống sét..), công việc cụ thể:</p><p>- Chủ trì khảo sát địa hình/ Chủ trì thiết kế kết câu công trình hạ tầng kỹ thuật viễn thông.</p><p>- Khảo sát, lập báo cáo khảo sát phục vụ các bước thiết kế công trình hạ tầng kỹ thuật viễn thông.</p><p>- Thiết kế, Ascending, thẩm tra thiết kế cơ sở, thiết kế kỹ thuật, thiết kế bản vẽ thi công công trình hạ tầng kỹ thuật viễn thông.</p><p>- Lập, thẩm tra dự án, dự toán công trình hạ tầng kỹ thuật viễn thông.</p><p>- Giám sát thi công công trình hạ tầng kỹ thuật viễn thông.</p><p>- Kiểm tra cơ sở hạ tầng trạm thu phát sóng.</p><p>&nbsp;</p>', '<p>-Độ tuổi : Từ 35 tuổi trở xuống</p><p>-Tốt nghiệp bằng khá trở lên chuyên ngành kỹ thuật xây dựng/Kết cấu công trình dân dụng, công nghiệp/Trắc địa, bản đồ</p><p>-Tốt nghiệp chính quy tại các trường sau:</p><p>1. Đại học xây dựng</p><p>2. Đại học Bách Khoa</p><p>3. Đại học Mỏ - địa chất</p><p>4. Đại học kiến trúc</p><p>5. Đại học giao thông vận tải</p><p>Hoặc các trường nước ngoài thuộc nhóm 1.000 trường đại học tốt nhất.</p><p>- Ưu tiên ứng viên có chứng chỉ hành nghề hoạt động xây dựng lĩnh vực thiết kế kết cấu công trình/ khảo sát địa hình (còn thời hạn tối thiểu sau ngày 30/06/2026).</p><p>&nbsp;</p><p>2. Về trình độ Tiếng Anh: trình độ tối thiểu đạt bậc 3/6 khung năng lực ngoại ngữ 6 bậc dùng cho Việt Nam (được quy định tại thông tư số 01/2014/TT-BGDĐT ngày 24/01/2014 của Bộ giáo dục và đào tạo) hoặc trình độ B, hoặc tương đương trình độ B1 khung tham chiếu chung Châu Âu (CEFR), ưu tiên các ứng viên có chứng chỉ tiếng anh quốc tế: Toeic, IELTS,... và các chứng chỉ quốc tế khác.</p>', '<p><strong>LƯƠNG THƯỞNG: Mức thu nhập từ 250 triệu – 350 triệu/năm</strong></p><p><strong>CHẾ ĐỘ PHÚC LỢI:</strong></p><p>1. Được hưởng các khoản quà tặng 8/3, 20/10, gia đình Việt Nam cho cả nhân viên nam và nữ.</p><p>2. Thưởng lễ - Tết, ngày thành lập Trung tâm/Tổng công ty, thưởng hoàn thành kế hoạch sản xuất kinh doanh, được hỗ trợ ăn ca, điện thoại liên lạc, chế độ nghỉ mát, du xuân.</p><p>3. Tham gia chương trình bảo hiểm sức khỏe cho CBCNV và người thân của MobiFone với mức bảo hiểm lên đến 8.000.000đ/ngày.</p><p>4. Khám sức khỏe định kỳ 1 năm/lần.</p><p>5. Được hưởng chế độ thuê bao liên lạc nghiệp vụ.</p>', '- Hà Nội: Tòa nhà Mobifone, 6 Phúc Lý, Phường Minh Khai, Quận, Bắc Từ Liêm', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'TRUNG TÂM CÔNG NGHIỆP CÔNG NGHỆ CAO MOBIFONE - CHI NHÁNH TỔNG CÔNG TY VIỄN THÔNG', '20 -30 Triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286798949_mobifone.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(118, 1, 'recruiter', NULL, 'post', N'Nhân Viên Số Hóa Dữ Liệu (Không Yêu Cầu Kinh Nghiệm - Đi Làm Ngay) Lương 7-10M/Tháng', 'active', 71, 0, 0, '2025-06-03 20:15:03.333', '2025-06-30 19:33:03.110', NULL, 'Không yêu cầu', '2025-07-01', 'Thứ 2 - Thứ 7 (từ 08:00 đến 17:00)', '<p><i><strong>1. Tiếp nhận & phân loại tài liệu:</strong></i></p><p>- Nhận, kiểm tra và phân loại hồ sơ/tài liệu giấy theo đúng quy định</p><p>- Loại bỏ vật cản ảnh hưởng đến quá trình scan như ghim, kẹp...</p><p><i><strong>2. Scan tài liệu:</strong></i></p><p>- Vận hành máy scan (máy để bàn, máy công nghiệp...) để quét tài liệu</p><p>- Kiểm tra hình ảnh sau scan, đảm bảo chất lượng rõ nét, không mờ, thiếu trang</p><p><i><strong>3. Nhập liệu & kiểm tra dữ liệu:</strong></i></p><p>- Nhập thông tin từ tài liệu vào phần mềm theo biểu mẫu</p><p>- Đối chiếu, kiểm tra độ chính xác giữa dữ liệu gốc và dữ liệu nhập</p><p><i><strong>4. Hỗ trợ công việc khác:</strong></i></p><p>- Xử lý lỗi phát sinh trong quá trình scan/nhập liệu</p><p>- Báo cáo tiến độ, số lượng công việc hằng ngày cho quản lý</p>', '<p>- Không yêu cầu kinh nghiệm – được đào tạo đầy đủ trước khi làm việc, ưu tiên sinh viên đã/sắp tốt nghiệp các ngành: <i>Công nghệ thông tin, Hệ thống thông tin, Kinh tế, Quản trị kinh doanh, Kế toán, Lưu trữ - Văn thư, Ngôn ngữ, Kỹ thuật...</i></p><p>- Cẩn thận, nhanh nhẹn, tỉ mỉ, trung thực và có trách nhiệm</p><p>- Sử dụng tin học văn phòng cơ bản, đặc biệt là Excel</p><p>- Có khả năng đánh máy ổn định</p><p>- Tuân thủ nội quy làm việc, bảo mật thông tin trong suốt thời gian làm việc</p>', '<p><strong>- Thực tập với mức lương khởi điểm: 7.000.000 - 10.000.000VNĐ/tháng (fulltime), dựa theo mức độ hoàn thành KPI - thu nhập không giới hạn.</strong></p><p>- Được cấp <strong>Giấy chứng nhận tham gia Dự án Chuyển đổi số Quốc gia</strong>, ghi nhận đóng góp cá nhân cho công cuộc hiện đại hóa đất nước</p><p>- Hỗ trợ <strong>xác nhận thực tập</strong>.</p><p>- Tiếp cận quy trình số hóa chuyên nghiệp, công nghệ tiên tiến</p><p>- Được đào tạo kỹ năng nghiệp vụ bài bản, thử việc trong 2 tuần.</p><p>- Thưởng hiệu suất: Thưởng vượt định mức, hoàn thành sớm tiến độ.</p><p>- Cơ hội rèn luyện kỹ năng và phát triển trong lĩnh vực <strong>IT, Nhân viên Xử lý/Phân tích Dữ liệu, Nhân viên số hóa, Tester/QA...</strong></p>', '- Hà Nội: Cầu Giấy - Hà Nội: Nam Từ Liêm - Hà Nội: Bắc Từ Liêm ...và 3 địa điểm khác', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'CÔNG TY CỔ PHẦN RIKKEI EDUCATION', '7 - 10 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286783108_rikkei.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(121, 1, 'recruiter', NULL, 'post', N'Nhân Viên Kinh Doanh/ Tư Vấn Giải Pháp Phần Mềm (Nghỉ T7, CN) Thu Nhập 10-30Tr', 'active', 42, 0, 0, '2025-06-04 08:14:19.310', '2025-06-30 19:32:37.770', NULL, '1 năm', '2025-07-31', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00) Thứ 7 (từ 08:00 đến 12:00)', '<p>- Tiếp nhận nguồn DATA từ bộ phận Marketing, thực hiện gọi ra để tư vấn giải pháp phần mềm cho khách hàng bằng kịch bản có trước. (70%)<br>- Tự phát triển thêm nguồn data cá nhân để nâng cao doanh số. (30%)<br>- Đối tượng khách hàng: các CEO, chủ doanh nghiệp và cấp quản lý của các công ty.<br>- Tư vấn, hướng dẫn, chốt/triển khai hợp đồng với khách hàng qua điện thoại, email hoặc gặp trực tiếp khách hàng (trong trường hợp KH yêu cầu).<br>- Chăm sóc khách hàng trước & sau bán, chủ động thăm hỏi lại các khách hàng cũ.<br>- Thực hiện một số công việc khác theo yêu cầu của Trưởng nhóm Kinh doanh.<br>- Báo cáo công việc trực tiếp cho Trưởng nhóm Kinh doanh.</p>', '<p>- Nam/Nữ, tuổi từ 20 - 30. Tốt nghiệp từ Cao đẳng trở lên.<br>- Giọng nói: lưu loát, không ngọng. Tự tin giao tiếp & thuyết trình trước khách hàng.<br>- Có kinh nghiệm làm sale, telesale, chăm sóc Khách hàng, hoặc BD (Business Development) hoặc BA (Business Analyst) từ tối thiểu 6 tháng.<br>- Ứng viên có thiết bị làm việc (laptop) và phương tiện cá nhân (xe máy/xe điện)<br>- Tư duy logic, có khả năng teamwork, có kỹ năng lập kế hoạch làm việc theo tuần/tháng/quý.<br>- Chăm chỉ, trung thực, có trách nhiệm trong công việc.<br>- Ưu tiên ứng viên tốt nghiệp các chuyên ngành Kinh tế, QTKD, MKT, CNTT, Kế toán,... hoặc có hiểu biết về lĩnh vực CNTT, phần mềm.<br>- Ứng viên đã có kinh nghiệm làm sales sản phẩm công nghệ, quản trị doanh nghiệp, phần mềm, CNTT là một lợi thế.<br>- Chân dung ứng viên mong muốn: Làm việc theo phương châm: Sáng tạo - Chủ động, Bền bỉ - Hiệu quả, Đồng đội - Biết ơn.</p><p>&nbsp;</p><h3>Thu nhập</h3><ul><li>Thu nhập khi đạt 100% KPI: 10 - 30 triệu VND</li><li>Thu nhập tính theo tỷ lệ đạt KPI</li><li>Lương cứng: 7 - 10 triệu VND</li><li>Lương cứng không phụ thuộc doanh số</li></ul>', '<p>- Lương cơ bản theo cấp bậc: từ <strong>7.000.0000 - 10.000.000</strong> + phụ cấp (ăn trưa, xăng xe, con nhỏ) + Thưởng P3 (KPI) + thưởng doanh số (được hưởng ngay trong thời gian thử việc).</p><p>- Thu nhập trung bình: 10.000.000 - 20.000.000đ<br>- Thưởng Tháng, Quý, Cuối năm theo Chính sách Công ty.</p><p>- Thưởng Lễ, Tết, hỗ trợ hiếu hỉ, sinh nhật theo quy định Công ty.</p><p>- Tham gia chương trình team building, du lịch, khám sức khoẻ định kỳ (thâm niên >6 tháng)</p><p>- Thời gian thử việc tối đa 2 tháng.<br>- Khi thành nhân viên chính thức được tham gia bảo hiểm theo các chính sách theo Quy định của nhà nước.</p><p>- Được đào tạo về sản phẩm, kĩ năng bán hàng và xử lý tình huống.<br>- Có lộ trình thăng tiến rõ ràng theo bậc<br>- Thời gian làm việc: Từ thứ 2 - thứ 6 (8h - 17h30), nghỉ T7 & CN</p><p>&nbsp;</p><h3>Phụ cấp</h3><p>Ăn trưa, Xăng xe, Cước điện thoại</p><h3>Thiết bị làm việc</h3><p>Được cấp Điện thoại, Tai nghe</p><h3>Quyền lợi</h3><p>Bảo hiểm xã hội, Khám sức khỏe định kỳ, Team building, Du lịch hàng năm, Phụ cấp thâm niên, Thưởng tháng 13, Thưởng hiệu quả làm việc, Signing bonus</p>', '- Hà Nội: Toà nhà Hoa Cương, số 18 ngõ 11 Thái Hà, Đống Đa - Hồ Chí Minh: 43D/9 Hồ Văn Huê, Phường 09, Phú Nhuận', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'CÔNG TY CỔ PHẦN CÔNG NGHỆ GETFLY VIỆT NAM', '10 - 30 triệu', 'Hà Nội, Hồ Chí Minh', 'Full-time', 'uploads/company_logos/1751286757770_GetFly.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(132, 1, 'recruiter', NULL, 'post', N'Trưởng Phòng Vận Hành (Dĩ An - Bình Dương Lương 30 - 40 Triệu)', 'active', 32, 0, 0, '2025-06-11 21:57:45.490', '2025-06-30 19:37:17.200', NULL, 'Trên 5 năm', '2025-07-11', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) Thứ 7 cách tuần', '<p>- Tổ chức, sắp xếp kế hoạch xe phục vụ nhu cầu của khách hàng.</p><p>- Đánh giá chất lượng dịch vụ, tham mưu cho ban lãnh đạo công ty phương án vận hành nhằm tối ưu hóa chi phí, và giảm thiểu phát sinh liên quan đến chất lượng dịch vụ.</p><p>- Phối hợp với phòng quản lý phương tiện để đảm bảo xe được quản lý và sử dụng với chất lượng tốt nhất.</p><p>- Lên kế hoạch phân công công việc cho nhân sự trong phòng, theo dõi đánh giá định kì từ đó có đề xuất phù hợp nhằm nâng cao hiệu suất trong công việc.</p><p>- Phối hợp cùng phòng mua hàng/kế toán lên kế hoạch phân bổ sắp xếp tuyến chạy hợp lý cho đội xe và xe của nhà thầu phụ.</p><p>- Đánh giá định kì để các nhà thầu phụ để nâng cao năng lực phục vụ và khả năng đáp ứng xe vào những đợt cao điểm, sale, các dự án lớn.</p><p>- Phối hợp cùng phòng Hành chính nhân sự tuyển dụng, đào tạo, sử dụng tài xế hiệu quả, duy trì theo nề nếp.</p><p>- Các công việc khác có liên quan theo sự phân công của Ban giám đốc.</p>', '<p>- Nam có sức khỏe tốt, nhanh nhạy nhiệt tình trung thực, kỹ năng giao tiếp tốt, không ngại di chuyển.</p><p>- Kinh nghiệm: >5 năm trong ngành Vận tải/ Logistics, điều phối xe tải. Trong đó có ít nhất 2 năm kinh nghiệm Quản Lý Đội Xe Tải.</p><p>- Các ứng viên có kinh nghiệm về kỹ thuật xe tải, Có bằng lái xe từ B2 trở lên là lợi thế.</p><p>- Tin học văn phòng tốt.</p><p><strong>- Làm việc tại Số 7, Đại lộ Độc Lập, KCN Sóng Thần 1, Dĩ An, Bình Dương</strong></p>', '<p>- Lương: 30-40 triệu/ tháng (theo năng lực) thử việc hưởng 90% lương.</p><p>- Phúc lợi:</p><p>+ Tham gia BHXH, BHYT, BHTN theo quy định sau 2 tháng thử việc.</p><p>+ Công ty xét tăng lương/ thăng tiến 1 lần/năm.</p><p>+ Team building/du lịch theo kế hoạch hàng năm của công ty.</p>', '- Bình Dương: Số 7, Đại lộ Độc Lập, KCN Sóng Thần 1, Dĩ An - Hồ Chí Minh: Củ Chi', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'Công Ty TNHH A Sóc', '30 - 40 triệu', 'Hồ Chí Minh', 'Full-time', 'uploads/company_logos/1751286737382_Asoc.webp', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
(133, 1, 'recruiter', NULL, 'post', N'Sales Representative – Đại Diện Kinh Doanh Tại Hà Nội, Ưu Tiên Nữ, Thu Nhập 20-30 Triệu Theo Năng Lực', 'active', 59, 0, 0, '2025-06-11 23:05:28.267', '2025-06-30 19:31:55.157', NULL, '1 năm', '2025-07-12', 'Từ 8h30-17h30 các ngày thứ 2 đến thứ 6 – thứ 7 luân phiên', '<p>- Phát triển và duy trì mối quan hệ tốt với khách hàng dựa trên danh sách khách hàng được công ty cung cấp</p><p>- Là cầu nối liên hệ trực tiếp với khách hàng trong tất cả các bước của việc bán hàng bao gồm nhưng không giới hạn:</p><p>+ Tìm hiểu nhu cầu/mong muốn thực sự của khách hàng</p><p>+ Giới thiệu sản phẩm và tư vấn các giải pháp phù hợp</p><p>+ Chào giá, thương lượng và ký hợp đồng mua bán</p><p>+ Theo dõi và thông báo khách hàng kế hoạch lắp đặt dự kiến</p><p>+ Chịu trách nhiệm thông báo và thu hồi các khoản thanh toán của khách hàng</p><p>+ Chăm sóc khách hàng sau bán hàng</p><p>- Kết hợp đội kỹ thuật khảo sát công trình/nhà ở thực tế</p><p>- Cập nhật tình trạng khách hàng trên hệ thống bán hàng của công ty</p><p>- Đạt doanh số bán hàng được chỉ định</p><p>- Đi công tác tại các tỉnh/thành khác</p>', '<p>- Ưu tiên nữ từ 26 - 27 tuổi trở lên</p><p>- Tốt nghiệp Cao đẳng trở lên các ngành kinh tế, kinh doanh, ngoại ngữ...</p><p>- Có kinh nghiệm ở vị trí nhân viên kinh doanh (là một lợi thế)</p><p>- Mong muốn thu nhập tốt thông qua làm việc chăm chỉ và hướng đến mục tiêu cụ thể</p><p>- Thật sự yêu thích công việc bán hàng và tiếp xúc với khách hàng</p><p>- Ứng viên phải là người trung thực và khiêm tốn</p><p>- Tự tin, thoải mái/thân thiện trong giao tiếp</p><p>- Có ý thức chủ động và trách nhiệm công việc</p><p>- Thích nghi nhanh và chịu được áp lực công việc</p><p>- Có tinh thần cầu tiến với mong muốn ngày càng phát triển bản thân</p><p>- Hợp tác tốt với nhóm bán hàng và các phòng/ban khác của công ty</p><p>- Sử dụng thành thạo các ứng dụng Ms Office</p><p>- Tiếng Anh giao tiếp tốt (là một lợi thế)</p><p>- Thời gian làm việc: Từ 8h30-17h30 các ngày thứ 2 đến thứ 6 – thứ 7 luân phiên</p><p>- Làm việc ngoài giờ hoặc cuối tuần sẽ theo điều động của Giám đốc hoặc theo thực tế công việc yêu cầu.</p><p>&nbsp;</p><h3>Thu nhập</h3><ul><li>Thu nhập khi đạt 100% KPI: Thoả thuận</li><li>Thu nhập tính theo tỷ lệ đạt KPI</li><li>Lương cứng: Từ 10 triệu VND trở lên</li><li>Lương cứng không phụ thuộc doanh số</li></ul>', '<p>- Làm việc tại Công ty của nước ngoài, môi trường chuyên nghiệp, có nhiều cơ hội thăng tiến</p><p>- Thu nhập lên đến: 20-30tr (tuỳ năng lực)</p><p>- BHYT, BHXH, BHTN, nghỉ phép năm... theo quy định của Luật Lao động Việt Nam</p><p>- Bảo hiểm sức khỏe nhân viên</p><p>- Du lịch trong nước và nước ngoài</p><p>- Tham gia chương trình đào tạo phát triển kỹ năng chuyên môn</p>', '- Hà Nội: Tầng 03, P303, số 239 Xuân Thủy, P. Dịch Vọng Hậu, Cầu Giấy', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'CÔNG TY TNHH CIBES LIFT VIỆT NAM', 'Thỏa Thuận', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286715148_cibes.webp', NULL, 'Nhân Viên', 'Kinh Doanh', 'HR', '22 - 99 Nhân viên', 'https://cibeslift.com.vn/', NULL, 'Chuyên môn Sales Representative/Phát triển kinh doanh Direct Sales Telesales B2B B2C Có hỗ trợ Data Từ 26 tuổi trở lên'),
(134, 2, 'recruiter', NULL, 'post', N'Content Marketing/ Sáng Tạo Nội Dung - Kinh Nghiệm 2 Năm (Thu Nhập 12 -16 Triệu)', 'active', 113, 0, 0, '2025-06-12 14:43:27.637', '2025-06-30 19:36:25.213', NULL, '2 năm', '2025-07-12', '8h - 17h30 từ T2 đến hết sáng T7; nghỉ trưa: 12h00 – 13h30', '<p>- Xây dựng kế hoạch sáng tạo nội dung để phát triển kênh Tiktok, Facebook chuyển đổi của công ty</p><p>- Booking KOC hàng tháng để sản xuất nội dung</p><p>- Liên tục cập nhập số liệu và insights của người dùng về sản phẩm để đề xuất những ý tưởng sáng tạo</p><p>- Báo cáo hiệu quả công việc theo campaign/ tuần/ tháng để đánh giá hiệu quả và có đề xuất phù hợp cho hệ thống Social</p>', '<p>- Nam/ nữ từ 23 - 26 tuổi</p><p>- Tốt nghiệp Đại học chính quy, chuyên ngành Báo chí, Marketing, PR hoặc các chuyên ngành liên quan</p><p><strong>- Có kinh nghiệm từ 02 năm trở lên về vị trí Content Marketing hoặc các vị trí tương đương</strong></p><p>- Am hiểu sâu nghiệp vụ về Marketing, công cụ Marketing</p><p>- Có khả năng viết nội dung và giao tiếp tốt</p><p>- Thành thạo các phần mềm chỉnh sửa video như Capcut, Canva,...</p><p>- Có tinh thần cầu tiến, kiên trì, tâm huyết, đam mê, mong muốn phát triển bản thân.</p>', '<p><strong>- Lương cứng: 7tr5 - 9 triệu + thưởng doanh số; Thu nhập 12-16 triệu</strong></p><p>- Hưởng 12 ngày nghỉ phép/năm; hưởng đầy đủ chế độ BHXH, BHYT, BHTN theo đúng Luật lao động Việt Nam hiện hành;</p><p>- Thưởng danh hiệu thi đua 1 lần/năm;</p><p>- Thưởng cuối năm theo kết quả kinh doanh của Công ty và hiệu quả làm việc của CBNV;</p><p>- Được hưởng các chính sách phúc lợi theo quy định của công ty: Sinh nhật; Du lịch 2 lần/năm; hoạt động Teambuilding;...</p><p>- Môi trường làm việc trẻ trung, năng động, được phát huy tối đa sức sáng tạo.</p><p>- Thời gian làm việc: 8h - 17h30 từ T2 đến hết sáng T7; nghỉ trưa: 12h00 – 13h30</p>', '- Hà Nội: Tòa nhà AC Building, số 3, ngõ 78, Duy Tân, Dịch Vọng Hậu, Cầu Giấy', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'CÔNG TY CỔ PHẦN THƯƠNG MẠI VÀ ĐẦU TƯ BABY AND MOM GLOBAL', '12 - 16 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286985213_bmg.png', NULL, 'Nhân Viên', 'Create Content', 'HR', '10-24 nhân viên', 'uni-techgroup.com', 'BABY AND MOM GLOBAL (viết tắt BMG) được thành lập với mục tiêu nghiên cứu và sản xuất các sản phẩm Mẹ & bé chất lượng vượt trội, giá thành hợp lý đáp ứng nhu cầu thị trường trong và ngoài nước. BMG hướng tới trở thành trung tâm phân phối các dòng sản phẩm mẹ và bé từ đa quốc gia trên toàn thế giới.', 'Chuyên môn Content Marketing'),
(178, 2, 'recruiter', NULL, 'post', N'Chuyên Viên Tư Vấn Môi Trường 2 Năm Kinh Nghiệm - Lương Upto 15tr - Tại Hà Nội', 'active', 100, 0, 0, '2025-06-18 20:42:56.277', '2025-06-30 19:36:10.060', NULL, '2 năm', '2025-07-12', 'Làm việc từ Thứ hai đến Thứ sáu và 02 ngày thứ Bảy cách tuần (08h00 - 17h30)', '<p>- Lập hồ sơ môi trường: Báo cáo đánh giá tác động môi trường, Báo cáo xin cấp Giấy phép môi trường, Báo cáo Vận hành thử nghiệm,...</p><p>- Thực hiện các công việc liên quan đến lĩnh vực môi trường.</p><p>- Hỗ trợ các phòng ban khác (khi có yêu cầu).</p><p>- Tư vấn cho khách hàng về các vấn đề thủ tục pháp lý và kỹ thuật liên quan đến môi trường.</p>', '<p><strong>- Kinh nghiệm ở vị trí tương đương từ 02 năm trở lên (đã trực tiếp thực hiện Báo cáo ĐTM/Giấy phép môi trường/...).</strong></p><p>- Tốt nghiệp Đại học trở lên các chuyên ngành liên quan đến môi trường.</p><p>- Kỹ năng phân tích, tổng hợp dữ liệu tốt.</p><p>- Khả năng làm việc độc lập và làm việc nhóm.</p><p>- Kỹ năng làm việc logic, sắp xếp công việc, nhạy bén trong xử lý tình huống, trao đổi thông tin với khách hàng.</p><p>- Chịu được áp lực công việc cao.</p><p>- Thành thạo MS, sử dụng AutoCad cơ bản, đọc hiểu bản vẽ.</p><p>- Sẵn sàng đi công tác (khi cần thiết).</p>', '<p>- Lương cơ bản: 10 - 15 triệu/tháng (chưa bao gồm Lương thưởng, phụ cấp).</p><p>- Lương thưởng: tháng thứ 13, thưởng dự án, thưởng hiệu suất công việc.</p><p>- Phụ cấp: Ăn trưa, xăng xe, công tác,...</p><p>- Chế độ phúc lợi: sinh nhật, các ngày lễ,...</p><p>- Tham gia BHXH, BHTN, BHYT đầy đủ theo Luật Lao động quy định.</p><p>- Xét duyệt tăng lương dựa trên năng lực, hiệu suất công việc.</p><p>- Du lịch hàng năm.</p><p>- Làm việc từ Thứ hai đến Thứ sáu và 02 ngày thứ Bảy cách tuần (08h00 - 17h30).</p>', '- Hà Nội: Số 1, ngõ 37, phố Lê Thanh Nghị, phường Bách Khoa, Hai Bà Trưng', '<p>Ứng viên nộp hồ sơ trực tuyến bằng cách bấm <strong>Ứng tuyển</strong> ngay dưới đây.</p>', 'CÔNG TY CỔ PHẦN TẬP ĐOÀN UNI-TECH', '10 - 15 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286970057_uni-tech.webp', NULL, 'Nhân Viên', 'Chuyên môn Kỹ sư môi trường', 'HR', '10-24 nhân viên', 'uni-techgroup.com', NULL, 'Chuyên môn Kỹ sư môi trường'),
(180, 2, 'recruiter', NULL, 'post', N'Chuyên Viên ASO - Mobile App Marketing Tại Hà Nội Thu Nhập 18 - 25 Triệu', 'active', 1, 0, 0, '2025-06-21 21:00:35.980', '2025-06-21 21:00:35.980', '2025-06-21 21:00:45.647', '2 năm', '2025-07-11', 'Thứ 2 - Thứ 6 (từ 08:30 đến 17:30) Thứ 7 cách tuần', '<p>a</p>', '<p>a</p>', '<p>a</p>', '- Hà Nội: Tâng 2B, Capital Building, Ngõ 36 Giang Văn Minh, Ba Đình', '<p>a</p>', 'Công Ty Cổ Phần Công Nghệ Dịch Vụ Y Tế Medici', '18 - 25 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1750514435963_delasoi.png', NULL, 'Nhân Viên', 'Kinh Doanh', 'HR', '22 - 99 Nhân viên', 'uni-techgroup.com', 'aaaa', 'Chuyên môn Content Marketing'),
(181, 2, 'recruiter', NULL, 'post', N'Nhân Viên Quảng Cáo/ Marketing ADs Đa Kênh (Facebook, Google, TikTok...) – Tối Thiểu 1 Năm Kinh Nghiệm - Tại Hà Nội', 'active', 36, 0, 0, '2025-06-23 21:44:41.260', '2025-06-30 19:35:57.680', NULL, '1 năm', '2025-07-12', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '<p><strong>• Lên kế hoạch & triển khai quảng cáo trên các nền tảng: Facebook, Instagram, Google, TikTok.</strong></p><p>• Quản lý ngân sách quảng cáo theo kế hoạch của công ty.</p><p>• Theo dõi, phân tích hiệu quả chiến dịch → đề xuất cải tiến.</p><p>• Phối hợp với phòng MKT để xây dựng nội dung, hình ảnh quảng cáo đẹp, chuẩn luxury.</p><p>• Báo cáo kết quả định kỳ cho quản lý.</p>', '<p><strong>• Có kinh nghiệm chạy Ads tối thiểu 1 năm trong ngành FMCG / bán lẻ / luxury / e-commerce.</strong></p><p>• Biết tối ưu chi phí, hiểu về tệp khách hàng cao cấp là lợi thế.</p><p>• Có tư duy phân tích số liệu, biết đọc chỉ số Ads.</p><p>• Làm việc có trách nhiệm, chủ động, chịu được áp lực KPI.</p><p><strong>• Ưu tiên ứng viên từng làm trong các team nhỏ, làm trực tiếp cho brand.</strong></p>', '<p><strong>• Lương thoả thuận theo năng lực + thưởng hiệu quả Ads.</strong></p><p><strong>• Được tiếp xúc & làm trong môi trường thương hiệu luxury cao cấp.</strong></p><p><strong>• Có cơ hội mở rộng tư duy & kỹ năng chạy Ads chuyên sâu.</strong></p><p><strong>• Môi trường làm việc nhanh - linh hoạt - minh bạch - ít phức tạp.</strong></p>', '- Hà Nội: Văn phòng Omiyage Fruits & More Bắc Từ Liêm, gần Cầu Giấy (Shophouse 30 - H6 - Khu đô thị Starlake Tây Hồ Tây), Bắc Từ Liêm', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'OMIYAGE FRUITS & MORE', 'Thỏa Thuận', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286957678_Fruits.webp', NULL, 'Nhân Viên', 'Kinh Doanh', 'HR', '25 - 99 Nhân viên', 'https://www.omiyage.com.vn', 'Câu Chuyện Omiyage Và Văn Hóa Tặng Quà Của Nhật Bản Omiyage trong tiếng Nhật có nghĩa là "món quà". Không chỉ đại diện cho nền văn hóa "cho – nhận" của người Nhật, Omiyage còn thể hiện sự trân trọng giá trị con người. Với ý nghĩa đẹp đẽ này, Omiyage cam kết từng sản phẩm của chúng tôi đưa ra thị trường đều chỉn chu, hoàn mỹ, song hành cùng chất lượng cao, chứa đựng tâm huyết của đội ngũ cửa hàng lẫn tình cảm của người tặng và người nhận. Các sản phẩm của chúng tôi sẽ thay quý khách trao yêu thương đến những người bạn trân trọng để nhận lại hạnh phúc. Omiyage tự hào mang đến những loại trái cây nhập khẩu cao cấp nhất với chất lượng tuyệt hảo, phong phú lựa chọn và đa dạng theo mỗi mùa, mỗi đất nước. Trái cây thượng phẩm tại Omiyage không chỉ là thực phẩm ngon, tốt cho sức khỏe, mang đến những trải nghiệm nâng tầm vị giác cho quý khách và gia đình, đây còn là những sản phẩm siêu VIP được dùng để biếu tặng mang nhiều ý nghĩa về may mắn, tài lộc và phú quý.', 'Chuyên môn Marketing Tuổi 23 - 30'),
(182, 2, 'recruiter', NULL, 'post', N'Nhân Viên Thiết Kế Nội Thất (2D/3D) - Từ 1 Năm Kinh Nghiệm, Lương Cứng 10-15 Triệu', 'active', 2, 0, 0, '2025-06-23 22:10:10.500', '2025-06-30 19:35:40.947', NULL, '1 năm', '2025-08-01', 'Thứ 2 - Thứ 7 (từ 08:30 đến 18:00)', '<p>- Tham gia vào quá trình thiết kế nội thất cho các dự án nhà ở, văn phòng, khách sạn, nhà hàng, các Mô hình kinh doanh và không gian thương mại khác</p><p>- Triển khai phương án thiết kế 2D, 3D nội - ngoại thất</p><p>- Phối hợp với khách hàng để hiểu rõ nhu cầu và mong muốn của họ, đưa ra các đề xuất thiết kế phù hợp</p><p>- Lựa chọn và đề xuất vật liệu, màu sắc, đồ nội thất phù hợp với concept thiết kế</p><p>- Chuẩn bị các bản vẽ kỹ thuật và tài liệu cần thiết cho quá trình thi công</p><p>- Theo dõi và hỗ trợ bộ phận thi công để đảm bảo thi công thực hiện đúng theo thiết kế</p><p>- Cập nhật kiến thức về xu hướng thiết kế nội thất mới nhất và áp dụng vào các dự án</p>', '<p><strong>- Tốt nghiệp Đại học/Cao đẳng trở lên chuyên ngành Kiến trúc; Nội thất;</strong></p><p><strong>- Tối thiểu 1-3 năm kinh nghiệm tại vị trí thiết kế nội thất</strong></p><p>- Kinh nghiệm sử dụng AutoCAD, Sketchup, Photoshop...</p><p>- Có kiến thức về các quy chuẩn, tiêu chuẩn thiết kế công trình.</p><p>- Kỹ năng thiết kế, lên mặt bằng phương án công năng.</p><p>- Có trách nhiệm trong công việc, khả năng chủ động xử lý trong công việc, có kỹ năng làm việc nhóm tốt.</p><p>- Năng động, trung thực, có khả năng làm việc độc lập, chịu được áp lực về tiến độ công việc, sẵn sàng làm thêm vào những thời điểm gấp của dự án.</p>', '<p>- Lương cứng 10-15 triệu + % thưởng công trình: Thoả thuận theo năng lực</p><p>- Có cơ hội tiếp xúc với các công trình, dự án quy mô lớn để nâng cao năng lực.</p><p>- Được hưởng các chế độ theo quy định của Nhà nước.</p><p>- Thưởng các ngày lễ, tết theo quy định của nhà nước</p><p>- Môi trường rèn luyện bản thân tốt, năng động, sáng tạo</p>', '- Hà Nội: C10-29 GELEXIMCO C – LÊ TRỌNG TẤN, Hà Đông', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'CÔNG TY CỔ PHẦN THƯƠNG MẠI N - ONE VIỆT NAM', '10 - 15 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286940948_One vn.webp', NULL, 'Nhân Viên', 'Thiết kế / Kiến trúc', 'HR', '25 - 99 Nhân viên', 'https://n-one.vn/', 'CÔNG TY KIẾN TRÚC & NỘI THẤT N-ONE VIỆT là đơn vị chuyển tư vấn, thiết kế thi công, sản xuất nội thất, xây dựng, kết cấu nhà thép. Thiết kế thi công các chuỗi mô hình kinh doanh, CLB Billiard, Nhà hàng, Khách sạn, Cafe, Bar Club, Các công trình biệt thự, nhà phố, căn hộ, chung cư và đặc biệt thiết kế trang trí văn phòng, showroom, bar vũ trường... Công ty gồm 80-100 nhân viên - với hệ thống chi nhánh 3 miền thành lập và phát triển trên 10 năm, Chúng tôi tự tin đem đến cho khách hàng những sản phẩm tốt nhất, Tạo ra những ưu thế và khắc phục những nhược điểm cân bằng chi phí trong thiết kế thi công hoàn thiện công trình.', 'Chuyên môn Marketing/PR/Quảng cáo khác Thực phẩm / Đồ uống Bán lẻ - Hàng tiêu dùng - FMCG Tiếng Anh Giao tiếp cơ bản Tuổi 23 - 30'),
(183, 2, 'recruiter', NULL, 'post', N'Nhân Viên IT / IT Helpdesk/ IT Support - Ngành Viễn Thông, Khu Vực Đồng Nai', 'active', 13, 0, 0, '2025-06-23 22:14:03.400', '2025-06-30 19:35:30.107', NULL, 'Không yêu cầu', '2025-07-16', '- Giờ làm việc hành chính: từ 7h30-17h00.', '<p>- Vận hành hệ thống máy tính, phần mềm, quản lý mạng internet tại văn phòng.</p><p>- Quản lý mạng internet cung cấp cho Khách hàng.</p><p>- Nghiên cứu các giải pháp công nghệ mới vô áp dụng phát triển công nghệ thông tin mới.</p>', '<p><strong>- Yêu cầu giới tính: Nam, dưới 40 tuổi</strong></p><p>&nbsp;</p><p>- Kinh nghiệm: 3 năm trở lên vị trí tương đương</p><p>- Tốt nghiệp Cử nhân công nghệ thông tin</p><p><strong>- Ưu tiên kinh nghiệm làm việc trong môi trường Viễn thông, Lắp đặt Mạng - Truyền thông</strong></p>', '<p>- Thu nhập: 8 triệu - 12 triệu thỏa thuận</p><p>- Giờ làm việc hành chính: từ 7h30-17h00.</p><p>- Được nghỉ 4 ngày / tháng.</p><p>- Được tham gia BHXH, BHYT, BHTN, 24/24.</p><p>- Chế độ phúc lợi: nghỉ mát hàng năm, thưởng các ngày lễ: 30/4, 2/9, tết dương lịch, tết nguyên đán,...</p><p>- Quà công đoàn: Sinh nhật, quốc tế thiếu nhi 1/6, trung thu, tết âm lịch,...</p><h3><strong>Thiết bị làm việc</strong></h3><p>Được cấp Máy tính</p><h3><strong>Quyền lợi</strong></h3><p>Bảo hiểm xã hội, Bảo hiểm sức khỏe, Team building, Thưởng tháng 13, Thưởng hiệu quả làm việc</p>', '- Đồng Nai: Biên Hoà', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'CHI NHÁNH CÔNG TY CỔ PHẦN CÔNG NGHỆ VIỆT THÀNH', '8 - 15 triệu', 'Đồng Nai', 'Full-time', 'uploads/company_logos/1751286930106_Vtvcab.webp', NULL, 'Nhân Viên', 'Marketing / Truyền thông / Quảng cáo', 'HR', '100-499 Nhân viên', NULL, 'Công ty Cổ Phần Công Nghệ Việt Thành được chuyển đổi từ Công ty TNHH Công Nghệ Việt Thành, theo giấy chứng nhận ĐKKD số 0302807495 cấp lần đầu vào ngày 13/12/2002, thay đổi lần thứ 15, ngày 19/12/2016 tại Sở Kế Hoạch Đầu tư TP.HCM. Trải qua hơn 15 năm hoạt động, tới nay Công ty đã liên tục tăng vốn để mở rộng quy mô hoạt động sản xuất kinh doanh, và đã đạt được nhiều thành quả trong quá trình kinh doanh dịch vụ truyền hình cáp. Hiện tại, Công ty đã có trên 250,000 thuê bao là các hộ gia đình với hàng triệu khán giả xem truyền hình; thực hiện tốt nghĩa vụ với ngân sách nhà nước và tạo công ăn việc làm cho gần 400 người lao động tại TPHCM và Đồng Nai. Ngày 3/6/2013, Ủy ban chứng khoán nhà nước đã có văn bản số 2212/UBCK-QLPH chấp thuận hồ sơ đăng ký công ty đại chúng của Công ty CP Công nghệ Việt Thành. Ngày 11/01/2017, Công ty CP Công nghệ Việt Thành đã được Cục Viễn Thông, Bộ Thông Tin Truyền Thông cấp Giấy phép THIẾT LẬP MẠNG VIỄN THÔNG CÔNG CỘNG.', 'Chuyên môn Marketing/PR/Quảng cáo khác Thực phẩm / Đồ uống Bán lẻ - Hàng tiêu dùng - FMCG Tiếng Anh Giao tiếp cơ bản Tuổi 23 - 30'),
(184, 2, 'recruiter', NULL, 'post', N'Nhân Viên Kinh Doanh Tư Vấn Quốc Tế - Sales Oversea/ Xuất Nhập Khẩu (Tiếng Anh/ TIếng Trung)', 'active', 19, 0, 0, '2025-06-23 22:17:49.453', '2025-06-30 19:34:58.920', NULL, '1 năm', '2025-07-10', '- Giờ làm việc hành chính: từ 7h30-17h00.', '<p>- Dựa trên nền tảng dữ liệu Công ty cung cấp, tìm hiểu đối tác nước ngoài và đặt mối quan hệ hợp tác cung cấp chuỗi dịch vụ logistics đến khách hàng.</p><p>- Giới thiệu và chào bán tất cả các dịch vụ Logistics, cước Sea freight, Air freight, Container leasing, Warehouse, ...</p><p>- Tư vấn giải pháp tối ưu cho việc vận chuyển hàng hóa, tuyến đường, ...</p><p>- Quản lý danh sách khách hàng, các đơn hàng đã và đang sử dụng dịch vụ</p>', '<p>- <strong>Sử dụng tiếng Anh hoặc Tiếng Trung cơ bản. Biết và thành thạo các thứ tiếng khác là một lợi thế.</strong></p><p>- Có 1 năm kinh nghiệm</p><p>- Tốt nghiệp các trường Đại Học/ Cao Đẳng có liên quan ngành nghề xuất nhập khẩu Logistics như Đại Học Ngoại thương, Thương Mại, Cao Đẳng Kinh tế đối ngoại, Kinh doanh quốc tế, ...</p><h3><strong>Thu nhập</strong></h3><ul><li>Thu nhập khi đạt 100% KPI: 15 - 50 triệu VND</li><li>Thu nhập tính theo tỷ lệ đạt KPI</li><li>Lương cứng: 6 - 20 triệu VND</li><li>Lương cứng phụ thuộc vào doanh số</li></ul>', '<p><strong>- Thu Nhập từ 15 - 50 Triệu = LCB (6-16 Triệu) + Thưởng doanh số + Phụ Cấp</strong></p><p>- Có cơ hội đi công tác nước ngoài, mở rộng giao lưu các nền văn hóa, ...</p><p>- Có cơ hội được tham gia các lớp đào tạo nghiệp vụ ngắn hạn, đào tạo phát triển kỹ năng & làm việc với các đối tác uy tín, chuyên nghiệp.</p><p>- Môi trường làm việc chuyên nghiệp, năng động và thân thiện. Có nhiều cơ hội thăng tiến với những chế độ đãi ngộ hấp dẫn - lâu dài và ổn định.</p><p>- Được hưởng các chế độ phúc lợi theo quy định Nhà nước: BHXH, BHYT, BHTN, nghỉ phép, tháng lương 13, thưởng lễ tết, Sinh nhật Công ty, ...</p><p>- Các chế độ theo quy định của công ty: Du lịch hàng năm, tham gia hoạt động team building, dã ngoại, ... và nhiều chế độ đãi ngộ hấp dẫn khác.</p>', '- Hà Nội: Cầu Giấy', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'Công ty Cổ phần Quốc Tế TICO', '15-50 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286898919_TICO.webp', NULL, 'Nhân Viên', 'Logistics - Vận tải', 'HR', '25 - 99 Nhân viên', 'https://ticog.com/', 'Công ty Cổ Phần Quốc tế TICO là Công ty hoạt động chuyên nghiệp về dịch vụ Logistics, được thành lập từ năm 2005, trụ sở tại Hà Nội và các Chi nhánh tại HCM, Hải Phòng và Đà Nẵng. Các hoạt động chủ yếu về vận tải quốc tế bằng đường biển, đường hàng không, đường bộ, thủ tục hải quan, kho vận, Depot, NVOCC ... Là thành thành viên của các hiệp hội vận tải quốc tế WCA, FNC, IGLA, JC TRANS, … Website chính thức của Công ty: www.ticog.com', 'Chuyên môn Sales Xuất nhập khẩu/Logistics khác'),
(185, 2, 'recruiter', NULL, 'post', N'Chuyên Viên Truyền Thông & Sự Kiện (Event Marketing) - Thu Nhập 18-20 Triệu - Tại Hà Nội', 'active', 48, 0, 0, '2025-06-23 22:22:24.863', '2025-06-30 19:34:43.003', NULL, '3 năm', '2025-07-19', 'Thứ 2 - Thứ 6 (từ 08:00 đến 17:00)', '<p><strong>1. Tổ chức sự kiện</strong></p><p>Xây dựng, cải tiến các quy trình, quy định về quản lý, tổ chức sự kiện, triển khai giám sát công tác tổ chức sự kiện đảm bảo tuân thủ theo quy định;</p><p>Tổng hợp thông tin, xây dựng, cập nhật, triển khai thực hiện kế hoạch sự kiện hàng năm, ngắn hạn của Công ty;</p><p>Chủ động chuẩn bị và triển khai sự kiện theo phân công, quy định. Phối hợp với các Bộ phận, đối tác khách hàng, nhà cung cấp triển khai sự kiện, đảm bảo an toàn, hiệu quả đúng kế hoạch và tiết kiệm, triển khai các thủ tục thanh toán liên quan;</p><p>Xây dựng và nâng cấp, cập nhật thông tin, cơ sở dữ liệu liên quan đến sự kiện, nhà cung cấp, đối tác;</p><p>Tham mưu, nghiên cứu, đề xuất hình thức tổ chức sự kiện một cách khoa học, tiên tiên, hợp lý, trang trọng, hiệu quả và tiết kiệm</p><p><strong>2. Truyền thông nội bộ</strong></p><p>Xây dựng kế hoạch Truyền thông nội bộ của công ty hằng tháng, quý, năm</p><p>Xây dựng và quản lý nội dung, hình ảnh các kênh Truyền thông nội bộ của công ty</p><p>Chủ trì xây dựng và phát triển, sản xuất các ấn phẩm nội bộ của công ty. Thường xuyên cập nhật xu hướng để phát triển nội dung sáng tạo, thu hút.</p><p>Đề xuất các kế hoạch xây dựng, phát triển văn hóa doanh nghiệp.</p><p><strong>3. Hoạt động PR Báo chí</strong></p><p>Thực hiện Thông cáo báo chí, đón tiếp báo chí tại sự kiện</p><p>Phối hợp sản xuất tin bài truyền thông;</p><p>Booking và làm việc với báo chí sản xuất tin bài, phóng sự;</p><p>Tham gia xử lý khủng hoảng truyền thông;</p><p>Xây dựng và phát triển thương hiệu, thực hiện kế hoạch truyền thông theo yêu cầu;</p><p>Thực hiện đánh giá báo cáo, triển khai các hoạt động đo lường hiệu quả MKT, PR theo yêu cầu</p><p><strong>4. Marketing tổng hợp (30%)</strong></p><p>Nghiên cứu các sản phẩm, nhãn hàng, ngành hàng của Phan Nguyễn;</p><p>Lên các nội dung chi tiết về sản phẩm, nhãn hàng và trình bày trên Slide sao cho cô đọng, nổi bật, dễ hiểu;</p><p>Đào tạo nội bộ, đối tác theo các nội dung đã chuẩn bị;</p><p>Tham gia lập các kế hoạch Marketing nhãn hàng;</p><p>Các công việc khác về Marketing theo yêu cầu.</p><p><strong>5. Phối hợp với các phòng ban liên quan và thực hiện các nhiệm vụ khác theo phân công.</strong></p>', '<ul><li>Tốt nghiệp Đại học trở lên chuyên ngành Kinh tế, Quản trị kinh doanh, Marketing.</li><li>Kinh nghiệm: tối thiểu 03 năm kinh nghiệm về Marketing. Có tối thiểu 01 năm làm việc với vị trí Chuyên viên PR – Marketing hoặc vị trí tương đương. Ưu tiên có kinh nghiệm tại các công ty sản xuất/phân phối hàng gia dụng/tiêu dùng nhanh/mẹ và bé.</li><li>Có quan hệ với các bên báo chí, Agency, truyền hình</li><li>Tin học: thành thạo tin học văn phòng (Word, Excel, Power Point, Outlook...)</li><li>Am hiểu kiến thức chuyên môn về Marketing</li><li>Kiến thức và kinh nghiệm về truyền thông, báo chí, sự kiện</li><li>Hiểu biết về ngành hàng liên quan</li><li>Kỹ năng:</li><li>Giải quyết vấn đề</li><li>Giao tiếp tốt</li><li>Làm việc nhóm và làm độc lập việc hiệu quả</li><li>Quản lý thời gian</li></ul>', '<p><strong>- Tổng thu nhập: 18- 20 triệu (Lương CB từ 17-19 triệu + Thưởng KPI + Phụ cấp ăn trưa + Thưởng chuyên cần).</strong></p><p><strong>Thử việc tháng đầu hưởng 85% lương, tháng thứ 2 hưởng 100% lương.</strong></p><p>- Các chính sách thưởng, phúc lợi theo quy định của Công ty: Lương tháng 13, Thường ngày lễ. Quà các ngày (Sinh nhật, tết thiếu nhi, tết trung thu, Quốc tế phụ nữ, Phụ nữ Việt Nam).</p><p>- Được hưởng phép năm sau khi hoàn thành thử việc: 01 ngày / tháng</p><p>- Tham gia Team Building, Du lịch, sự kiện hàng năm do Công ty tổ chức.</p><p>- Người lao động được tham gia BHXH, BHYT, BHTN theo quy định của Công ty.</p><p>- Tăng lương định kỳ (tháng 01 hàng năm). Xét duyệt tăng trước thời hạn khi có thành tích xuất sắc.</p><p>- Môi trường làm việc năng động, thân thiện, cơ hội thăng tiến.</p>', '- Hà Nội: 671 Hoàng Hoa Thám, Ba Đình', 'Ứng viên nộp hồ sơ trực tuyến bằng cách bấm Ứng tuyển ngay dưới đây.', 'CÔNG TY CP ĐẦU TƯ VÀ THƯƠNG MẠI QUỐC TẾ PHAN NGUYỄN', '18 - 20 triệu', 'Hà Nội', 'Full-time', 'uploads/company_logos/1751286883003_TTMQT.webp', NULL, 'Nhân Viên', NULL, 'HR', '100-499 Nhân viên', 'https://pncom.vn', 'CÔNG TY CP ĐẦU TƯ VÀ THƯƠNG MẠI QUỐC TẾ PHAN NGUYỄN là đơn vị tiên phong nhập khẩu và phân phối hàng Organic có chứng nhận quốc tế. Với hơn 3000 đại lý lớn nhỏ trải dài từ Bắc vào Nam, Phan Nguyễn là doanh nghiệp hàng đầu tại Việt Nam hoạt động trong lĩnh vực F&B và FMCG với thế mạnh là các sản phẩm hữu cơ, góp phần tạo ra xu hướng sống xanh, sống khoẻ. 1. TẦM NHÌN: Trở thành doanh nghiệp uy tín hàng đầu phân phối các sản phẩm hữu cơ, các sản phẩm dinh dưỡng và sức khỏe tại Việt Nam. 2. SỨ MỆNH: Góp phần thay đổi nhận thức, thói quen cho cộng đồng trong việc tiêu dùng các sản phẩm chất lượng, tạo dựng một thế hệ khỏe mạnh, một môi trường sống xanh và sạch. 3. TÍN: Phan Nguyễn luôn đặt chữ TÍN lên hàng đầu, luôn đảm bảo các cam kết của mình với khách hàng, đối tác. Mọi sản phẩm hữu cơ đều được lựa chọn kỹ càng, có chứng nhận rõ ràng từ những tổ chức uy tín hàng đầu thế giới. 4. TÂM: Chữ TÂM là nền tảng triết lý kinh doanh của Phan Nguyễn. Khách hàng luôn được đặt lên vị trí hàng đầu', 'Chuyên môn Event Marketing Báo chí');


